package com.fintrack.khmtomnenh.quotation.entity; import com.fasterxml.jackson.annotation.*; import com.fintrack.khmtomnenh.auth.entity.Auth; import com.fintrack.khmtomnenh.rfq.entity.Rfq; import com.fintrack.khmtomnenh.quotationitem.entity.QuotationItem; import jakarta.persistence.*; import lombok.*; import java.math.*; import java.time.*; import java.util.*; import org.hibernate.annotations.CreationTimestamp; import org.hibernate.annotations.UpdateTimestamp;
@Entity @Table(name="quotations") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class Quotation {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @JsonIgnore @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="rfq_id") private Rfq rfq; @JsonIgnore @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="supplier_id") private Auth supplier; @Column(precision=19,scale=2,nullable=false) private BigDecimal totalAmount; @Builder.Default @Column(nullable=false) private String status="SUBMITTED"; private String notes; @CreationTimestamp @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt; @JsonManagedReference @OneToMany(mappedBy="quotation",cascade=CascadeType.ALL,orphanRemoval=true) @Builder.Default private List<QuotationItem> items=new ArrayList<>();}
